import{z as s,x as A,o as e,c as p,q as t,j as B,D as E,d as i,s as l,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"保留价","description":"","frontmatter":{"title":"保留价","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/auction-reserve.md","filePath":"econ/auction-reserve.md","lastUpdated":1791063341000}'),d={name:"econ/auction-reserve.md"};function h(m,a,D,u,c,C){const n=A("Mermaid");return e(),p("div",null,[a[2]||(a[2]=t('<h1 id="保留价" tabindex="-1">保留价 <a class="header-anchor" href="#保留价" aria-label="Permalink to &quot;保留价&quot;">​</a></h1><div class="epigraph"><p>最优保留价由虚拟价值过零处决定，不随投标人数上升而下降；卖家故意留下正概率不成交，用效率换信息租金。</p><footer>—— Myerson, Optimal Auction Design, Mathematics of Operations Research, 1981；Riley and Samuelson, Optimal Auctions, American Economic Review, 1981</footer></div><p><a href="/econ/second-price-vickrey">上一课</a>钉了二价占优真话：最高报价得物，付第二高。缺口是卖方自己的估值 \\(v_0\\)（常取 \\(0\\)）不必等于「必须成交」。加上保留价 \\(r\\)：所有报价低于 \\(r\\) 则物品留在卖方。真话仍占优，但配置不再总把物品交给最高 \\(v_i\\)。本课钉最优 \\(r\\)，不把收入等价的整条包络提前，也不把虚拟价值熨平写成全书。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对称 IPV，风险中性。二价加保留价：报 \\(v_i\\) 仍是占优；若最高报价 \\(\\lt r\\)，不成交；若恰好一人超过 \\(r\\)，付 \\(r\\)；若至少两人超过 \\(r\\)，付第二高报价。卖方期望收入随 \\(r\\) 先升后降：太低则把物品廉价卖给接近 \\(0\\) 的类型；太高则经常卖不掉。</p><p>Myerson / Riley–Samuelson：正则分布下，最优 \\(r^*\\) 满足虚拟价值为零，</p> \\[\\varphi(r^*)=r^*-\\frac{1-F(r^*)}{f(r^*)}=0 \\]<p>（卖方估值 \\(v_0=0\\) 时）。关键比较静态：\\(r^*\\) <strong>不依赖</strong> \\(n\\)。多一个投标人提高成交概率，但不改变「边际类型该不该拿货」的虚拟价值公式。</p><p><span class="marginnote">数字实例：估值均匀分布在 0 到 100 之间时，\\(\\varphi(r)=2r-100\\)，令它为零得 \\(r^*=50\\)——底价恰好设在估值区间的中点，哪怕这意味着有一半的概率流拍也照样设。换成别的分布，\\(r^*\\) 会变，但解法都是同一个过零方程。</span></p><h3 id="不是「多来几个人就可以把-降到零」" tabindex="-1">不是「多来几个人就可以把 \\(r\\) 降到零」 <a class="header-anchor" href="#不是「多来几个人就可以把-降到零」" aria-label="Permalink to &quot;不是「多来几个人就可以把 $r$ 降到零」&quot;">​</a></h3><p>直觉说竞争越狠越不必设门槛。最优拍卖的会计相反：低类型成交会通过激励相容抬高所有更高类型的信息租金。挡掉 \\(\\varphi\\lt 0\\) 的类型，是在砍租金，不是在跟人数作对。人数进的是期望成交量，不进 \\(r^*\\) 的一阶条件。</p><p><span class="marginnote">若卖方自己有 \\(v_0\\gt 0\\)，门槛改成 \\(\\varphi(r)=v_0\\)。物品留在卖方，当且仅当所有投标人的虚拟价值都低于 \\(v_0\\)。有效性要求 \\(r=v_0\\)；收入最大化通常 \\(r^*\\gt v_0\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：对称独立、正则 \\(\\varphi\\) 递增、单物品。在二价（或英式）上加 \\(r\\)，用占优真话把期望收入写成 \\(r\\) 的函数，求导得 \\(\\varphi(r)=0\\)。一价加保留价改的是遮挡的下边界 \\(b(r)=r\\)，最优 \\(r\\) 在正则下与二价相同——这已经是收入等价的特例，本课只记结论，证明放后课。</p>',14)),(e(),B(o,null,{default:E(()=>[l(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20SP%5B%22%E4%BA%8C%E4%BB%B7%E7%9C%9F%E8%AF%9D%22%5D%20--%3E%20R%5B%22%E5%8A%A0%E4%BF%9D%E7%95%99%E4%BB%B7%20r%22%5D%0A%20%20R%20--%3E%20IC%5B%22%E7%9C%9F%E8%AF%9D%E4%BB%8D%E5%8D%A0%E4%BC%98%22%5D%0A%20%20R%20--%3E%20INEFF%5B%22%E6%AD%A3%E6%A6%82%E7%8E%87%E4%B8%8D%E6%88%90%E4%BA%A4%22%5D%0A%20%20PHI%5B%22%CF%86(r)%3D0%22%5D%20--%3E%20RSTAR%5B%22r*%20%E4%B8%8D%E9%9A%8F%20n%20%E5%8F%98%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"不对称先验、不规则密度要熨平，最优机制不再是「简单 \\(r\\) + 最高者得」，本课正则对称。英式加保留价：时钟从 \\(r\\) 起跳，或卖方委托出价顶到 \\(r\\)；策略仍是退到 \\(v\\)，只是 \\(v\\lt r\\) 者不参与。荷式 / 一价把下边界改成 \\(b(r)=r\\)，遮挡公式从 \\(r\\) 积分，不从 \\(0\\)。",-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[i("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,"包络把卖方收入钉成期望虚拟剩余。配置规则若把物品交给 \\(\\varphi\\lt 0\\) 的人，该项为负，不如留给卖方（\\(\\varphi\\) 记为 \\(0\\) 或 \\(v_0\\)）。保留价正是这道点态规则的公开写法：低于 \\(r^*\\) 的类型赢率为零。效率损失是故意的——与次优税同一逻辑：信息不对称下，第一最佳（总把物品给估值最高者）不可及，除非放弃收入目标。",-1)),a[6]||(a[6]=r("p",null,"人数增加：最高估值的分布往上移，成交更频繁，期望收入上升，但 \\(\\varphi(r)=0\\) 这条切线不变。所以「热门拍品仍设高底价」与「冷门拍品也设底价」可以来自同一公式，差别在 \\(F\\)，不在 \\(n\\)。",-1)),a[7]||(a[7]=r("p",null,[r("span",{class:"marginnote"},"直觉类比：把保留价想象成店主的「最低售价底线」。顾客越多，成交越容易，但店主不会因为今天客流量大就跌破底线甩卖——该不该按底线卖，取决于这件货本身值多少，跟排队人数无关。这就是 \\(r^*\\) 不随 \\(n\\) 变的日常版本。")],-1)),(e(),B(o,null,{default:E(()=>[l(n,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E4%BC%B0%E5%80%BC%E6%81%B0%E5%A5%BD%E5%8E%8B%E5%9C%A8%20r%20%E9%99%84%E8%BF%91%E7%9A%84%E8%BE%B9%E9%99%85%E4%B9%B0%E5%AE%B6%EF%BC%8C%E5%8D%96%E4%B8%8D%E5%8D%96%EF%BC%9F%22%5D%20--%3E%20S%5B%22%E5%8D%96%EF%BC%9A%E6%88%90%E4%BA%A4%E6%A6%82%E7%8E%87%E4%B8%8A%E5%8D%87%22%5D%0A%20%20D%20--%3E%20N%5B%22%E4%B8%8D%E5%8D%96%EF%BC%9A%E7%89%A9%E5%93%81%E7%95%99%E7%BB%99%E5%8D%96%E6%96%B9%EF%BC%8C%E8%AF%A5%E9%A1%B9%E8%AE%B0%E9%9B%B6%22%5D%0A%20%20S%20--%3E%20RENT%5B%22%E6%89%80%E6%9C%89%E6%9B%B4%E9%AB%98%E7%B1%BB%E5%9E%8B%E7%9A%84%E4%BF%A1%E6%81%AF%E7%A7%9F%E9%87%91%E8%A2%AB%E6%8A%AC%E9%AB%98%22%5D%0A%20%20RENT%20--%3E%20COST%5B%22%E4%BB%98%E5%87%BA%E5%8E%BB%E7%9A%84%E7%A7%9F%E9%87%91%E5%8F%AF%E8%83%BD%E8%B6%85%E8%BF%87%E6%88%90%E4%BA%A4%E6%94%B6%E7%9B%8A%22%5D%0A%20%20COST%20--%3E%20CMP%5B%22%E4%B8%A4%E8%BE%B9%E6%AF%94%E8%BE%83%EF%BC%9A%E5%93%AA%E4%B8%AA%E6%80%BB%E8%99%9A%E6%8B%9F%E5%89%A9%E4%BD%99%E6%9B%B4%E5%A4%A7%22%5D%0A%20%20N%20--%3E%20CMP%0A%20%20CMP%20--%3E%20ZERO%5B%22%E6%9C%80%E4%BC%98%E5%9C%A8%E5%88%86%E7%95%8C%E7%82%B9%EF%BC%9A%E8%99%9A%E6%8B%9F%E4%BB%B7%E5%80%BC%E6%81%B0%E8%BF%87%E9%9B%B6%20%CF%86(r*)%3D0%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=t('<h3 id="参与约束在最低类型" tabindex="-1">参与约束在最低类型 <a class="header-anchor" href="#参与约束在最低类型" aria-label="Permalink to &quot;参与约束在最低类型&quot;">​</a></h3><p>未参与的人支付为零。保留价把最低成交类型抬到 \\(r^*\\)，其租金为零。更高类型的租金仍是赢率的积分；砍掉低端赢率，整条租金曲线下移。这与筛选课「故意扭曲低类型数量」是同一包络。</p><p><span class="marginnote">进入费与保留价在 IPV 正则下可以互换（把参与门槛写成货币）。实务上公开 \\(r\\) 与隐藏底价、英式里卖方委托出价，实施不同，最优虚拟门槛可以相同。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>关联价值、风险厌恶、预算约束下，\\(r^*\\) 依赖 \\(n\\) 或不再由 \\(\\varphi=0\\) 单独给出。合谋时保留价还要防压价。也不要把保留价写成连续交易里的限价——本课是一次性拍卖的门槛。</p><p><span class="marginnote">常见误区：把流拍当成拍卖失败。最优机制里，正概率不成交是故意的——挡住低估值类型，等于压缩了高类型「假装自己是低类型」能占到的便宜，整条租金曲线随之下移；卖不掉本身就是压租金的工具。</span></p><p>后课默认：IPV 正则下最优保留价由虚拟价值过零决定，与人数无关；二价加 \\(r\\) 仍真话。下一课用包络把一价、荷式、英式的期望收入钉在同一条 \\(Q\\) 上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>二价加 \\(r\\)：真话仍占优，配置不再总有效。</li><li>最优 \\(r^*\\) 满足 \\(\\varphi(r^*)=0\\)，不随 \\(n\\) 下降。</li><li>卖方用不成交换更低的信息租金。</li><li>有效门槛是 \\(v_0\\)；收入最大化通常更高。</li><li>出处：Myerson, <em>Math. Oper. Res.</em>, 1981；Riley and Samuelson, <em>AER</em>, 1981。</li></ul>',9))])}const _=s(d,[["render",h]]);export{F as __pageData,_ as default};
